import React from "react";
import { useLocation, Route, Switch } from "react-router-dom";
import Footer from "components/Footer/Footer";
import routes from "routes.js";

function Admin() {
  const location = useLocation();
  const mainPanel = React.useRef(null);
  const [overlayOpen, setOverlayOpen] = React.useState(false);

  const getRoutes = (routes) =>
    routes.map((prop, key) =>
      prop.layout === "/admin" ? (
        <Route
          path={prop.layout + prop.path}
          render={(props) => <prop.component {...props} />}
          key={key}
        />
      ) : null
    );

  React.useEffect(() => {
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    if (mainPanel.current) mainPanel.current.scrollTop = 0;
  }, [location]);

  return (
    <>
      <div className="wrapper">
        <div
          className="main-panel"
          ref={mainPanel}
          style={{ width: "100%" }}
        >
          <div className="content">
            <Switch>{getRoutes(routes)}</Switch>
          </div>
          <Footer />
        </div>
      </div>

      {/* 🔘 Floating Menu Button (ทุกหน้า ทุกจอ) */}
      <button
        onClick={() => setOverlayOpen(true)}
        style={{
          position: "fixed",
          top: "16px",
          right: "16px",
          zIndex: 5000,
          width: "48px",
          height: "48px",
          borderRadius: "50%",
          border: "none",
          background: "#1DC7EA",
          color: "#fff",
          fontSize: "22px",
          cursor: "pointer",
        }}
      >
        ☰
      </button>

      {/* ⬛ Backdrop */}
      {overlayOpen && (
        <div
          onClick={() => setOverlayOpen(false)}
          style={{
            position: "fixed",
            inset: 0,
            width: "100vw",
            height: "100dvh",
            background: "rgba(0,0,0,0.4)",
            zIndex: 4000,
          }}
        />
      )}

      {/* 📋 Overlay Menu */}
      <div
        style={{
          position: "fixed",
          top: 0,
          right: 0,
          height: "100dvh",
          width: "280px",
          background:
            "linear-gradient(180deg, rgba(15,23,42,0.95), rgba(15,23,42,0.85))",
          color: "#fff",
          zIndex: 4500,
          padding: "24px 20px",
          transform: overlayOpen
            ? "translateX(0)"
            : "translateX(100%)",
          transition: "transform 0.3s ease",
          boxShadow: "-4px 0 20px rgba(0,0,0,0.4)",
        }}
      >
        <h4 style={{ marginBottom: "24px" }}>☰ MENU</h4>

        {[
          { name: "Dashboard", path: "/admin/dashboard", icon: "📊" },
          { name: "History", path: "/admin/history", icon: "📜" },
          { name: "Maps", path: "/admin/maps", icon: "🗺" },
        ].map((item) => (
          <div
            key={item.path}
            onClick={() => {
              setOverlayOpen(false);
              window.location.href = item.path;
            }}
            style={{
              cursor: "pointer",
              marginBottom: "16px",
              fontSize: "16px",
              padding: "10px 12px",
              borderRadius: "8px",
              background: "rgba(255,255,255,0.08)",
            }}
          >
            {item.icon} {item.name}
          </div>
        ))}
      </div>
    </>
  );
}

export default Admin;
